import React, { useReducer } from "react";
import Card from "../UI/Card/Card";
import Button from "../UI/Button/Button";
import classes from "./Login.module.css";
import Input from "../UI/Input/Input";

const formReducer = (state, action) => {
  if (action.type === "EMAIL_USER_INPUT") {
    const emailIsValid = action.email.includes("@");
    return {
      email: action.email,
      emailValid: emailIsValid,
      password: state.password,
      passwordValid: state.passwordValid,
      formValid: emailIsValid && state.passwordValid,
    };
  }

  if (action.type === "PASSWORD_USER_INPUT") {
    const passIsValid = action.password.trim().length > 6;

    return {
      email: state.email,
      emailValid: state.emailValid,
      password: action.password,
      passwordValid: action.emailValid,
      formValid: state.emailIsValid && passIsValid,
    };
  }

  if (action.type === "INPUT_BLUR") {
    const emailIsValid = state.email.includes("@");
    const passIsValid = state.password.trim().length > 6;
    return {
      email: state.email,
      emailValid: emailIsValid,
      password: state.password,
      passwordValid: passIsValid,
      formValid: emailIsValid && passIsValid,
    };
  }
  return {
    email: "",
    emailValid: false,
    password: "",
    passwordValid: false,
    formValid: false,
  };
};

const Login = (props) => {
  const [formState, dispatchForm] = useReducer(formReducer, {
    email: "",
    emailValid: false,
    password: "",
    passwordValid: false,
    formValid: false,
  });

  const emailChangeHandler = (event) => {
    dispatchForm({ type: "EMAIL_USER_INPUT", email: event.target.value });
  };

  const validateEmailHandler = () => {
    dispatchForm({ type: "INPUT_BLUR" });
  };

  const passwordChangeHandler = (event) => {
    dispatchForm({ type: "PASSWORD_USER_INPUT", password: event.target.value });
  };

  const validatePasswordHandler = () => {
    dispatchForm({ type: "INPUT_BLUR" });
  };

  const submitHandler = (event) => {
    event.preventDefault();
    props.onLogin(formState.email, formState.password);
  };

  return (
    <Card className={classes.login}>
      <form onSubmit={submitHandler}>
        <Input
            label="E-Mail"
            type="email"
            id="email"
            value={formState.email}
            onChange={emailChangeHandler}
            onBlur={validateEmailHandler}/>

        <div className={classes.actions}>
          <Button
            type="submit"
            className={classes.btn}
            disabled={!formState.formValid}
          >
            Login
          </Button>
        </div>
      </form>
    </Card>
  );
};

export default Login;
